mapper.update:
UPDATE subject
name = #{name}, code = #{code}, description = #{description}, credits = #{credits}, department_id = #{departmentId}, status = #{status}, sort_order = #{sortOrder},
WHERE id = #{id}

mapper.select:
SELECT s.id, s.department_id, s.name, s.code, s.description, s.credits, s.status, s.sort_order, s.create_time, s.update_time, s.deleted, d.dept_name as department_name FROM subject s LEFT JOIN department d ON s.department_id = d.id WHERE s.deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.department_id = #{departmentId}
ORDER BY s.sort_order ASC, s.id ASC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM subject WHERE deleted = 0
AND name LIKE CONCAT('%', #{name}, '%')
AND department_id = #{departmentId}
